# The reverse, built once at import rather than spelled twice. An ICAO code
# maps to at most one IATA code here, because the forward map refuses
# duplicates on either side.
ICAO_TO_IATA = {v: k for k, v in IATA_TO_ICAO.items()}


def icao_for(iata):
    """The ICAO code for a IATA code, or None. Case-insensitive."""
    return IATA_TO_ICAO.get(str(iata or "").strip().upper())


def iata_for(icao):
    """The IATA code for an ICAO code, or None. Case-insensitive."""
    return ICAO_TO_IATA.get(str(icao or "").strip().upper())
